let people=[],activities=[],page=1,activityLimit=100;const pageSize=18,$=s=>document.querySelector(s),fmt=n=>Number(n||0).toLocaleString(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),confidenceLabel=s=>{const value=String(s??'unknown');return value.charAt(0).toUpperCase()+value.slice(1)},normalize=s=>String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();function params(){return new URLSearchParams(location.search)}
function updateSearchUrl(){const p=new URLSearchParams(location.search);p.delete('person');p.set('q',$('#search').value);p.set('page',page);history.replaceState(null,'','people.html?'+p)}
function profileHref(key){const p=new URLSearchParams({person:key});if($('#search').value)p.set('q',$('#search').value);return 'people.html?'+p}
function renderResults(){const q=normalize($('#search').value),matches=people.filter(p=>!q||[p.name,p.citizenship,p.topPeak,...(p.peaks||[])].some(value=>normalize(value).includes(q))),start=(page-1)*pageSize,visible=matches.slice(start,start+pageSize);$('#result-count').textContent=(matches.length?start+1:'0')+'–'+Math.min(start+pageSize,matches.length)+' of '+matches.length+' profile'+(matches.length===1?'':'s')+(q?' matching':'');$('#results').innerHTML=visible.length?visible.map(p=>'<a class="result" href="'+profileHref(p.personKey)+'"><strong>'+esc(p.name)+'</strong><small>'+esc(p.citizenship||'Citizenship not recorded')+' · '+(p.birthYear?'born '+p.birthYear+' · ':'')+(p.firstYear||'-')+'–'+(p.lastYear||'-')+' · '+esc(p.topPeak||'No main peak')+'<br><b>'+fmt(p.appearances)+'</b> '+(p.possibleMerge?'source records':'expeditions')+' · <b>'+fmt(p.summits)+'</b> summits · <span class="confidence">'+esc(confidenceLabel(p.identityConfidence))+'</span></small></a>').join(''):'<div class="empty">'+(q?'No matching profile. Try a surname, citizenship, or peak.':'No profiles are available.')+'</div>';const pages=Math.max(1,Math.ceil(matches.length/pageSize));$('#pager').innerHTML='<button '+(page<=1?'disabled':'')+' data-page="prev">Previous</button><span>'+page+' / '+pages+'</span><button '+(page>=pages?'disabled':'')+' data-page="next">Next</button>';document.querySelectorAll('#pager button').forEach(button=>button.addEventListener('click',()=>{page+=button.dataset.page==='next'?1:-1;updateSearchUrl();renderResults()}))}
function renderProfile(p){$('#profile').hidden=false;$('#directory').hidden=true;document.title=p.name+' - Himalayas Explorer';$('#profile-name').textContent=p.name;if(p.easterEgg){$('#profile-meta').textContent='Curated site character · expedition companion';$('#identity-detail').innerHTML='<strong>About this entry:</strong> Freddy T. Bear is an educational expedition companion, included here as a Himalayas Explorer easter egg rather than a source-record identity.'}else{$('#profile-meta').textContent=(p.citizenship||'Citizenship not recorded')+' · '+(p.birthYear?'born '+p.birthYear+' · ':'birth year not recorded · ')+confidenceLabel(p.identityConfidence)+' confidence · identity match is provisional';$('#identity-detail').innerHTML='<strong>Why this confidence:</strong> '+esc(p.identityReason||'Identity reason not recorded')+'. This profile is a best-effort match and may change when the underlying records are updated.'};$('#merge-warning').hidden=!p.possibleMerge;$('#profile-appearances-label').textContent=p.possibleMerge?'Source records':'Expeditions';$('#profile-years-label').textContent=p.possibleMerge?'Recorded years':'Years active';$('#profile-appearances').textContent=fmt(p.appearances);$('#profile-summits').textContent=fmt(p.summits);$('#profile-peaks').textContent=fmt(p.peakCount||p.peaks.length);$('#profile-years').textContent=p.firstYear&&p.lastYear?p.firstYear+'–'+p.lastYear:'-';if(p.topPeak){$('#top-peak').hidden=false;$('#top-peak').innerHTML='<strong>Main recorded peak:</strong> <a href="peak.html?peak='+encodeURIComponent(p.topPeakId)+'">'+esc(p.topPeak)+'</a>. This is the most frequent peak in this identity group, not a confirmed career summary.'}loadActivity(p.personKey)}
function loadActivity(key){$('#activity-list').textContent='Loading activity…';fetch('expedition_members.json').then(response=>{if(!response.ok)throw Error('Member data file is missing');return response.json()}).then(rows=>{activities=rows.filter(x=>x.personKey===key).sort((a,b)=>b.year-a.year||String(a.expeditionId).localeCompare(String(b.expeditionId)));renderActivity()}).catch(error=>{$('#activity-list').innerHTML='<div class="empty">'+esc(error.message)+'. Run scripts/build_data.py, dbt build, and scripts/export_site_data.py.</div>'})}
function renderActivity(){const visible=activities.slice(0,activityLimit),person=people.find(p=>p.personKey===params().get('person'));$('#activity-list').innerHTML=visible.length?visible.map(x=>'<div class="activity-row"><div class="activity-year">'+x.year+'</div><div><a href="expedition.html?id='+encodeURIComponent(x.expeditionId)+'">'+esc(x.mountain)+' · expedition</a><br><span>'+esc(x.status)+(x.hired?' · hired/support':x.oxygen?' · oxygen used':'')+'</span></div><div class="tag '+(x.easterEgg?'mascot':x.died?'death':x.summit?'summit':'')+'">'+(x.easterEgg?'Mascot':x.died?(person&&person.possibleMerge?'Recorded death on row':'Death'):x.summit?'Summited':x.hired?'Hired':'Attempt')+'</div></div>').join(''):'<div class="empty">No activity rows found.</div>';$('#activity-pager').innerHTML=activities.length>activityLimit?'<button id="show-more">Showing '+activityLimit+' of '+activities.length+' · Show more</button>':'';const more=$('#show-more');if(more)more.addEventListener('click',()=>{activityLimit+=100;renderActivity()})}
function showNotFound(key){$('#directory').hidden=false;$('#error').hidden=false;$('#error').innerHTML='<strong>Profile not found.</strong><p>No profile matched '+esc(key)+'. Profile links may change when the underlying records are updated; return to the directory and choose a current profile.</p>'}
$('#search').addEventListener('input',()=>{page=1;clearTimeout(window.searchTimer);window.searchTimer=setTimeout(()=>{updateSearchUrl();renderResults()},150)});Promise.resolve().then(()=>fetch('people.json')).then(response=>{if(!response.ok)throw Error('People data file is missing');return response.json()}).then(rows=>{people=rows;const q=params().get('q');if(q)$('#search').value=q;page=Math.max(1,Number(params().get('page')||1));renderResults();const key=params().get('person');if(key){const profile=people.find(p=>p.personKey===key);profile?renderProfile(profile):showNotFound(key)}}).catch(error=>{$('#result-count').textContent='Build local data first';$('#directory').hidden=true;$('#error').hidden=false;$('#error').innerHTML='<strong>'+esc(error.message)+'</strong><p>Run scripts/build_data.py, dbt build, and scripts/export_site_data.py, then reload this page.</p>'});
